import {editCurveKeys} from './curve-tools.js';
// Vector records share time/interpolation. Only value/handle components are selected independently.
export function editCurveChannels(track,params){
 const {selections,...options}=params,keys=track.keys,shape=Array.isArray(keys?.[0]?.value)?keys[0].value.length:1;
 if(!Array.isArray(selections)||!selections.length||options.indices!==undefined||options.channel!==undefined||!['transform','flatten','straighten','linearTangents','smooth','fft'].includes(options.operation))throw Error('채널 선택과 값·탄젠트 도구를 확인하세요.');
 const seen=new Set(),groups=new Map();for(const row of selections){if(!row||Object.keys(row).some(k=>!['index','channels'].includes(k))||!Number.isInteger(row.index)||row.index<0||row.index>=keys.length||seen.has(row.index)||!Array.isArray(row.channels)||!row.channels.length||new Set(row.channels).size!==row.channels.length||row.channels.some(c=>!Number.isInteger(c)||c<0||c>=shape))throw Error('키 인덱스와 서로 다른 채널을 확인하세요.');seen.add(row.index);for(const c of row.channels){if(!groups.has(c))groups.set(c,[]);groups.get(c).push(row.index);}}
 const indices=[...seen].sort((a,b)=>a-b),time=i=>options.operation==='transform'?(options.timePivot??0)+(keys[i].time-(options.timePivot??0))*(options.timeScale??1)+(options.timeOffset??0):keys[i].time;
 const result=options.operation==='transform'?editCurveKeys(track,{...options,indices,valueScale:1,valueOffset:0,valuePivot:0}):structuredClone(track),byTime=new Map(result.keys.map(k=>[k.time,k]));if(byTime.size!==result.keys.length)throw Error('변환한 키 시간이 겹쳐요.');
 const initialized=new Set();for(const [channel,chosen]of groups){const next=editCurveKeys(track,{...options,...(options.operation==='transform'?{timeScale:1,timeOffset:0,timePivot:0}:{}),indices:chosen,channel});for(const i of chosen){const target=byTime.get(time(i)),key=next.keys[i];if(!target||!key)throw Error('변환한 키 시간을 확인하세요.');if(!initialized.has(i)){for(const field of ['arriveTangent','leaveTangent'])if(target[field]===undefined&&key[field]!==undefined)target[field]=structuredClone(key[field]);initialized.add(i);}target.interpolation=key.interpolation;for(const field of ['value','arriveTangent','leaveTangent','arriveWeight','leaveWeight']){if(key[field]===undefined)continue;if(Array.isArray(key[field])){target[field]??=field.endsWith('Weight')?keys[i].value.map(()=>1/3):structuredClone(key[field]);target[field][channel]=key[field][channel]/(options.operation==='transform'&&field.endsWith('Tangent')?(options.timeScale??1):1);}else target[field]=key[field]/(options.operation==='transform'&&field.endsWith('Tangent')?(options.timeScale??1):1);}}}
 return result;
}
export const curveChannelContract={selections:'Optional sequence.curve.tool selections: [{track,index,channels:[0..3]}], unique key rows and axes; replaces track/tracks/indices/channel selectors. Detached candidates validate together before one revision/Undo.',operations:['transform','flatten','straighten','linearTangents','smooth','fft'],units:'Raw authored values and slopes. Time transform once per vector key; selected component values/handles independently. Shared record time/interpolation/delete/copy remain whole-key operations; bake/reduce/Euler use existing whole-track selectors.',view:'Ctrl/Command toggles individual key components. Marquee and Select All choose visible components; hidden selected axes are removed. One drag applies inverse display delta per selected component and shared time once. View-only selection never changes revision.'};
